<script setup lang="ts">
import {ref,onMounted,onUnmounted} from 'vue';import {post,safeOfficialUrl,safeArticleUrl} from '../api/client';import {title,sourceName,time} from '../presentation/zh';import DateField from './DateField.vue';
const props=defineProps<{token:string}>();type Row=Record<string,any>;
const snapshot=ref<Row>(),reproduction=ref<Row>(),error=ref(''),busy=ref(false),country=ref(''),category=ref(''),verification=ref(''),minimum=ref(0),source=ref(''),overview=ref<Row>(),watches=ref<Row[]>([]),following=ref(''),watchOnly=ref(false),start=ref(''),end=ref(''),page=ref(0),catalog=ref<Row>({});
const filterMedia=window.matchMedia('(min-width:720px)');const filtersOpen=ref(filterMedia.matches);const syncFilters=()=>{filtersOpen.value=filterMedia.matches;};filterMedia.addEventListener('change',syncFilters);onUnmounted(()=>filterMedia.removeEventListener('change',syncFilters));
const categories=['货币政策','通货膨胀','就业','GDP','汇率','国际贸易','金融监管','重大企业披露','AI与半导体','光通信与数据中心','能源与大宗商品','产业链重大变化'];
const states:Row={EXTRACTED:'已提取待核验',SOURCE_CHECKED:'官方来源核查',FIELD_MATCHED:'事实字段核对',INDEPENDENT_SUPPORTED:'独立证据支持',CONFLICT:'证据冲突',REJECTED:'已否决',REVISED:'已修订',INSUFFICIENT:'证据不足'};
async function reproduce(){if(!snapshot.value||busy.value)return;busy.value=true;try{reproduction.value=await post('/practical/priority/reproduce',props.token,{id:snapshot.value.id});}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function rank(){reproduction.value=undefined;if(busy.value)return;busy.value=true;error.value='';try{snapshot.value=await post('/practical/priority/rank',props.token,{source:source.value,country:country.value,category:category.value,verification:verification.value,minimum:minimum.value,officialOnly:true,watchOnly:watchOnly.value,start:start.value?start.value+'T00:00:00+08:00':null,end:end.value?end.value+'T00:00:00+08:00':null});page.value=0;}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function paginate(n:number){if(busy.value||!snapshot.value)return;busy.value=true;error.value='';try{const next=page.value+n;snapshot.value=await post('/practical/priority/snapshot',props.token,{id:snapshot.value.id,page:next});page.value=next;}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
const followed=(id:string)=>watches.value.find(w=>w.kind==='EVENT'&&w.value===id&&w.enabled);
async function refreshOverview(){overview.value=await post('/practical/priority/overview',props.token);}
async function follow(r:Row){if(following.value)return;following.value=r.id;error.value='';try{const w=followed(r.id);watches.value=await post<Row[]>(w?'/watch/remove':'/watch/add',props.token,w?{id:w.id}:{kind:'EVENT',value:r.id,label:title(r).text.slice(0,200),includeLeads:false,minimumPriority:0});await refreshOverview();}catch(e){error.value=(e as Error).message;}finally{following.value='';}}
async function viewFollowed(){watchOnly.value=true;await rank();}
const ingestion:Row={NEW_EVENT:'真实新发布',HISTORICAL_BACKFILL:'历史回填',REVISION:'来源修订'};
const statuses:Row={SUCCESS:'最近检查成功',FAILED:'最近检查失败',RUNNING:'正在检查'};
onMounted(async()=>{try{catalog.value=await post('/practical/catalog',props.token);watches.value=await post<Row[]>('/watch/query',props.token);await refreshOverview();}catch(e){error.value=(e as Error).message;}await rank();});
</script>
<template><section class="panel feed"><h2>全球重要事件</h2><p>依据真实证据安排研究顺序。事实、统计观察、规则判断和研究假设分别呈现；分数不代表预测准确率或投资获利概率。</p><section v-if="overview" aria-label="真实事件概况" class="event-overview"><p>最近官方重要消息候选（近七日发布）：{{overview.recent_official_events}} 项；官方事件：{{overview.official_events}} 项。</p><p><button :disabled="busy" @click="viewFollowed">关注事件（{{overview.followed_events}}）</button> <a href="#/leads">待核验线索（{{overview.pending_leads}}）</a></p><p>数据更新时间：{{time(overview.data_updated_at)}}；实际查询：{{time(overview.queried_at)}}</p><details><summary>当前来源状态</summary><p v-for="s in overview.sources" :key="s.id">{{sourceName(s.id,s.name)}}：{{!s.enabled?'未启用':statuses[s.status]||'尚无检查记录'}}；{{s.http_status?'HTTP '+s.http_status:'未取得HTTP状态'}}；检查时间 {{time(s.finished_at)}}</p></details></section><p>官方研究候选与待核验线索分开展示。<a href="#/leads">打开待核验线索列表</a></p><details class="filter-panel" :open="filtersOpen"><summary>筛选重要事件</summary><div class="filters"><label>官方来源 <select v-model="source" :disabled="snapshot?.rule_version!=='重要事件研究排序-1.1'"><option value="">全部官方来源</option><option v-for="s in (catalog.sources||[]).filter((s:Row)=>s.level==='L0')" :key="s.id" :value="s.id">{{sourceName(s.id,s.name)}}</option></select></label><label>国家或地区 <select v-model="country"><option value="">全部</option><option v-for="r in [...new Set((catalog.sources||[]).map((s:Row)=>s.region))]" :key="String(r)" :value="r">{{r}}</option></select></label><label>事件与产业类型 <select v-model="category"><option value="">全部</option><option v-for="c in categories" :key="c">{{c}}</option></select></label><label>事实核验状态 <select v-model="verification"><option value="">全部</option><option v-for="(label,key) in states" :value="key" :key="key">{{label}}</option></select></label><label>最低研究优先级 <input type="number" min="0" max="100" v-model.number="minimum"></label><label>发布起始日期 <DateField v-model="start"/></label><label>发布截止日期（不含） <DateField v-model="end"/></label><label><input type="checkbox" v-model="watchOnly">仅个人关注</label><button :disabled="busy" @click="rank">生成可复核排序</button></div></details><p v-if="busy" role="status">正在冻结研究排序，请稍候…</p><p v-if="error" role="alert">{{error}}</p><template v-if="snapshot"><p v-if="snapshot.rule_version!=='重要事件研究排序-1.1'">此入口保持原运行版本。<a href="http://127.0.0.1:5178/#/important">打开本轮重要事件研究入口</a>，使用来源筛选与回填解释。</p><p>查询截止：{{time(snapshot.as_of)}} · 规则 {{snapshot.rule_version}} · 符合条件 {{snapshot.matched}} 项</p><p>{{snapshot.boundary}} {{snapshot.bounded?'候选达到5000条上限，请缩小日期或地区范围。':''}}</p><button :disabled="busy" @click="reproduce">复核此快照</button><p v-if="reproduction">复核结果：{{reproduction.reproduced?'冻结输入哈希与评分复算通过':'复核失败，不能据此确认排序'}}；输入 {{reproduction.input_count}} 项；评分差异 {{reproduction.score_mismatches}} 项。</p><code>快照 {{snapshot.id}} · 输入哈希 {{snapshot.input_hash}}</code><p v-if="!snapshot.rows.length">范围内暂无真实事件。</p><article v-for="r in snapshot.rows" :key="r.id" :data-event-id="r.id"><h3>{{title(r).text}}</h3><p>{{sourceName(r.source_id,r.publisher)}} · {{r.region}} · {{r.categories.join('、')||'类别尚未识别'}} · 研究优先级 {{r.score}}</p><p v-if="!r.intact" role="alert">证据哈希失败，不能视为已核实事实。</p><p>{{states[r.fact_status]||'待核验'}} · {{'来源等级 '+r.level}} · 发布时间 {{time(r.published_at,'官方发布时间未知')}}</p><p>{{ingestion[r.ingestion_kind]||'采集性质待核查'}} · 首次发现 {{time(r.first_seen_at)}} · {{title(r).status}}</p><p>关键事实摘要：{{r.value!=null?'实际观测值 '+r.value+'；观测期 '+r.observation_date:'实质事实与原文定位见研究详情，未补造金融数字。'}}</p><p v-if="r.actual_change?.difference!=null">同口径实际变化：{{r.actual_change.difference}}（单位见冻结输入）</p><p>主要排序依据：{{r.reasons.filter((x:string)=>/：\d+分$/.test(x)&&!x.endsWith('：0分')).slice(0,3).join('；')||'没有可用加分证据'}}</p><details><summary>为什么排在这里</summary><p v-for="reason in r.reasons" :key="reason">{{reason}}</p><p>{{r.cluster_basis}}；证据版本 {{r.revision}}</p><code>输入证据 {{r.evidence_id}} · SHA-256 {{r.raw_content_hash}}</code><details v-if="r.actual_inputs"><summary>实际评分输入</summary><pre>{{JSON.stringify(r.actual_inputs,null,2)}}</pre></details></details><details><summary>查看原文标题</summary><p>{{r.original_title}}</p></details><a :href="'#/research?event='+r.id">查看研究与历史证据</a><a v-if="safeOfficialUrl(r.source_url)||r.level!=='L0'&&safeArticleUrl(r.source_url)" :href="r.source_url" target="_blank" rel="noopener noreferrer">查看原始来源</a><button :disabled="!!following" @click="follow(r)">{{followed(r.id)?'取消事件关注':'关注此事件'}}</button></article><p>分页保持同一冻结快照。关注变更后重新生成排序，个人关注加分才会更新。</p><button :disabled="busy||page===0" @click="paginate(-1)">上一页</button><span>第 {{page+1}} 页</span><button :disabled="busy||(page+1)*50>=snapshot.matched" @click="paginate(1)">下一页</button></template></section></template>
<style scoped>input[type=number]{width:80px}code,article{overflow-wrap:anywhere}pre{white-space:pre-wrap;overflow-wrap:anywhere}.event-overview{margin:16px 0;padding:12px;border:1px solid #334155;border-radius:8px}a{margin-right:16px}label{max-width:100%}input[type=checkbox]{width:auto}</style>



